def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Extend each diagonal run outwards from its two ends.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color):
                    continue

                # The pair is (r,c) -> (nr,nc); continue away from each end.
                for sr, sc, step_r, step_c in (
                    (r, c, -dr, -dc),
                    (nr, nc, dr, dc),
                ):
                    rr, cc = sr + step_r, sc + step_c
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] != bg:
                            if grid[rr][cc] != color:
                                break
                        else:
                            out[rr][cc] = color
                        rr += step_r
                        cc += step_c

    return out
